"use client";

import { useState } from "react";
import { projects } from "@/data/projects";
import Link from "next/link";
import { ArrowRight, ExternalLink, Search } from "lucide-react";
import { cn } from "@/lib/utils";
import FinalCTA from "@/components/sections/FinalCTA";

const categories = ["All", "Web Development", "Full Stack", "EdTech", "Web Design"];

export default function ProjectsPage() {
  const [activeCategory, setActiveCategory] = useState("All");

  const filteredProjects = activeCategory === "All" 
    ? projects 
    : projects.filter(p => p.category === activeCategory);

  return (
    <div className="pt-44 pb-24">
      {/* Header */}
      <section className="px-6 mb-16 text-center">
        <div className="max-w-7xl mx-auto">
          <p className="text-primary text-sm font-bold uppercase tracking-[0.3em] mb-4">
            Our Portfolio
          </p>
          <h1 className="text-5xl md:text-7xl font-black text-white mb-8 font-outfit">
            Proven Results <br />
            <span className="text-gradient">Globally.</span>
          </h1>
          
          {/* Filters */}
          <div className="flex flex-wrap items-center justify-center gap-2 mt-12">
            {categories.map(cat => (
              <button
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={cn(
                  "px-6 py-2 rounded-full text-sm font-bold transition-all",
                  activeCategory === cat 
                    ? "bg-primary text-white shadow-lg shadow-primary/20" 
                    : "bg-white/5 text-white/40 hover:bg-white/10"
                )}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>
      </section>

      {/* Grid */}
      <section className="px-6 mb-24">
        <div className="max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-2 gap-12">
          {filteredProjects.map((project) => (
            <div 
              key={project.id}
              className="group glass rounded-[2.5rem] overflow-hidden hover:border-primary/50 transition-all duration-500"
            >
              <div className="aspect-[16/10] overflow-hidden relative">
                <img 
                  src={project.thumbnail} 
                  alt={project.title}
                  className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-background via-background/20 to-transparent" />
              </div>
              
              <div className="p-10">
                <div className="flex flex-wrap gap-2 mb-6">
                  {project.tags.map(tag => (
                    <span key={tag} className="px-3 py-1 bg-white/5 border border-white/10 rounded-full text-[10px] uppercase tracking-widest text-white/60 font-bold">
                      {tag}
                    </span>
                  ))}
                </div>
                
                <h3 className="text-3xl font-bold text-white mb-4 font-outfit group-hover:text-primary transition-colors">
                  {project.title}
                </h3>
                <p className="text-foreground/60 leading-relaxed mb-10 max-w-md">
                  {project.description}
                </p>

                <div className="flex items-center gap-8">
                  <Link 
                    href={`/projects/${project.slug}`}
                    className="flex items-center gap-2 text-white font-bold text-sm hover:text-primary transition-colors"
                  >
                    View Case Study <ArrowRight className="w-5 h-5" />
                  </Link>
                  <Link 
                    href="#"
                    className="flex items-center gap-2 text-white/40 font-bold text-sm hover:text-white transition-colors"
                  >
                    Live Preview <ExternalLink className="w-4 h-4" />
                  </Link>
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>

      <FinalCTA />
    </div>
  );
}
