"use client";

import Link from "next/link";
import { ArrowRight, MessageSquare, PhoneCall } from "lucide-react";

export default function FinalCTA() {
  return (
    <section className="section-padding px-6 bg-background relative overflow-hidden">
      {/* Background Decorative Elements */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[400px] bg-primary/20 blur-[150px] rounded-full pointer-events-none" />

      <div className="max-w-7xl mx-auto glass p-12 md:p-24 rounded-[4rem] text-center relative border-primary/20 overflow-hidden group">
        <div className="absolute inset-0 bg-gradient-to-br from-primary/5 via-transparent to-accent/5 opacity-0 group-hover:opacity-100 transition-opacity duration-700" />
        
        <div className="relative z-10">
          <h2 className="text-4xl md:text-6xl lg:text-7xl font-black text-white mb-10 font-outfit leading-tight tracking-tight">
            Ready to Build Something <br />
            <span className="text-gradient">Extraordinary?</span>
          </h2>
          <p className="text-foreground/60 text-lg md:text-xl lg:text-2xl max-w-3xl mx-auto mb-16 leading-relaxed">
            Join the collective. Let's transform your vision into a high-performance 
            digital reality that scales with your ambition.
          </p>

          <div className="flex flex-col sm:flex-row items-center justify-center gap-6">
            <Link 
              href="/contact"
              className="w-full sm:w-auto px-10 py-5 bg-primary text-white rounded-full font-bold shadow-2xl shadow-primary/40 hover:scale-105 transition-transform flex items-center justify-center gap-2 group/btn"
            >
              Start Your Project
              <ArrowRight className="w-5 h-5 group-hover/btn:translate-x-1 transition-transform" />
            </Link>
            
            <Link 
              href="https://wa.me/919140768903"
              className="w-full sm:w-auto px-10 py-5 bg-white/5 text-white border border-white/10 rounded-full font-bold backdrop-blur-sm hover:bg-white/10 transition-colors flex items-center justify-center gap-2"
            >
              <MessageSquare className="w-5 h-5 text-primary" />
              Chat on WhatsApp
            </Link>
          </div>

          <div className="mt-12 flex flex-col sm:flex-row items-center justify-center gap-8 text-white/40 text-sm">
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
              <span>Available for new projects</span>
            </div>
            <div className="hidden sm:block w-1 h-1 bg-white/10 rounded-full" />
            <div className="flex items-center gap-2">
              <PhoneCall className="w-4 h-4" />
              <span>Book a Strategy Call</span>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
